import subprocess
import time
import threading
def task_func(file_list):
    results = []
    def run_file(file):
        try:
            process = subprocess.Popen(file, shell=True)
            while process.poll() is None:
                time.sleep(0.1)
            results.append(process.returncode)
        except Exception:
            results.append(-1)
    threads = []
    for file in file_list:
        thread = threading.Thread(target=run_file, args=(file,))
        thread.start()
        threads.append(thread)
    for thread in threads:
        thread.join()
    return results
